vec3 aces(vec3 x){
return clamp((x*(2.51*x+.03))/(x*(2.43*x+.59)+.14),0.,1.);
}
float bayer4(vec2 px){
int x=int(mod(px.x,4.));
int y=int(mod(px.y,4.));
int i=x+y*4;
const int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5);
return(float(m[i])+.5)/16.;
}
float beatPulse(float phase,float k){
return exp(-k*phase);
}
float copperBar(vec2 uv,float phase,float k){
float y=uv.y*8.+beatPulse(phase,k)*2.;
return .5+.5*sin(y*3.14159265);
}
vec3 cosPalette(float t,vec3 a,vec3 b,vec3 c,vec3 d){
return a+b*cos(6.2831853*(c*t+d));
}
