float hash21(vec2 p){
uint h=floatBitsToUint(p.x)*2146503469u^floatBitsToUint(p.y)*1804288421u;
h=((h>>16u)^h)*1103515245u;
h=(h>>15u)^h;
return float(h>>8u)*(1./16777216.);
}
vec2 pixUV(vec2 fragCoord,vec2 res){
return(floor(fragCoord)+.5)/res;
}
float plasma2(vec2 uv,float t){
float v=sin(uv.x*4.+t)
+sin(uv.y*5.-t*1.3)
+sin((uv.x+uv.y)*3.+t*.7)
+sin(length(uv-.5)*6.-t*1.7);
return v*.25;
}
vec3 retroQuantize(vec3 col,const vec3 pal[16],int n,vec2 px){
float d=bayer4(px)-.5;
vec3 c=col+d*(1./float(n));
int best=0;
float bd=1e9;
for(int i=0;i<16;i++){
if(i>=n)break;
vec3 diff=c-pal[i];
float dd=dot(diff,diff);
if(dd<bd){bd=dd;best=i;}
}
return pal[best];
}
vec3 starfield(vec2 uv,float t,float speed){
vec2 g=floor(uv*24.);
vec2 f=fract(uv*24.);
float h=hash21(g);
vec2 star=vec2(hash21(g+1.7),hash21(g+9.2));
star+=.1*vec2(sin(t*(.3+h)+h*40.),cos(t*(.2+h)+h*31.));
float d=length(f-star);
float tw=.5+.5*sin(t*(2.+6.*h)+h*100.);
float lum=smoothstep(.08,0.,d)*(.4+.6*tw)*step(.75,h);
return vec3(lum);
}
int textChar(int i){
if(i<0||i>=uTextLen)return 32;
uint w=uint(uText[i>>2]);
return int((w>>(8u*uint(i&3)))&0xFFu);
}
vec3 toSRGB(vec3 c){
c=max(c,vec3(0.));
return mix(1.055*pow(c,vec3(1./2.4))-.055,c*12.92,step(c,vec3(.0031308)));
}
vec3 vignette(vec3 c,vec2 uv,float strength){
float d=distance(uv,vec2(.5));
return c*(1.-strength*smoothstep(.35,.85,d));
}
float drawGlyph(vec2 fragPx,vec2 origin,float scale,int code){
vec2 rel=(fragPx-origin)/scale;
if(rel.x<0.||rel.y<0.||rel.x>=8.||rel.y>=8.)return 0.;
uvec2 g=fontGlyph(code);
int col=int(rel.x);
int row=7-int(rel.y);
uint bits=(row<4)?(g.x>>(8u*uint(3-row))):(g.y>>(8u*uint(7-row)));
return float((bits>>(7u-uint(col)))&1u);
}
float drawText(vec2 fragPx,vec2 origin,float scale){
vec2 rel=(fragPx-origin)/scale;
if(rel.x<0.||rel.y<0.)return 0.;
int ci=int(rel.x/8.);
if(ci>=uTextLen||rel.y>=8.)return 0.;
return drawGlyph(fragPx,origin+vec2(float(ci)*8.*scale,0.),scale,textChar(ci));
}
vec3 grain(vec3 c,vec2 fragCoord,float amount){
float g=hash21(fragCoord+fract(iTime)*917.);
return c+(g-.5)*amount;
}
vec3 retroFinalize(vec3 col,vec2 uv,vec2 fragCoord,const vec3 pal[16],int n){
vec3 q=retroQuantize(clamp(col,0.,1.),pal,n,fragCoord);
float d=distance(uv,vec2(.5));
return q*(1.-.25*smoothstep(.45,.9,d));
}
const vec3 PALETTE[16]=vec3[16](
vec3(.02,.02,.05),vec3(.05,.05,.12),vec3(.1,.08,.25),
vec3(.2,.1,.4),vec3(.45,.15,.65),vec3(.75,.2,.75),
vec3(.95,.3,.65),vec3(1.,.55,.45),vec3(1.,.75,.3),
vec3(1.,.9,.45),vec3(.55,.95,.45),vec3(.2,.85,.55),
vec3(.1,.75,.85),vec3(.15,.45,.95),vec3(.45,.35,1.),
vec3(.95,.95,1.)
);
const int PALETTE_N=16;
vec3 finalize(vec3 col,vec2 uv){
#ifdef PROFILE_RETRO
return retroFinalize(col,uv,gl_FragCoord.xy,PALETTE,PALETTE_N);
#else
col=aces(col);
col=vignette(col,uv,.3);
col=grain(col,gl_FragCoord.xy,.015);
return toSRGB(col);
#endif
}

