void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 uv=pixUV(fragCoord,iResolution.xy);
float t=iTime;
float pl=plasma2(uv+vec2(0.,t*.05),t);
vec3 col=cosPalette(pl*.5+.5+uBar*.02,
vec3(.5),vec3(.5),vec3(1.),vec3(0.,.33,.67));
col+=starfield(uv+vec2(t*.01,0.),t,0.)*.8;
float speed=40.;
float textW=float(uTextLen)*8.;
float x0=iResolution.x+8.-mod(t*speed,textW+iResolution.x+16.);
float cov=drawText(fragCoord,vec2(x0,iResolution.y-20.),2.);
col=mix(col,vec3(1.,.9,.2),cov*(.7+.3*beatPulse(uBeatPhase,8.)));
float bar=step(uv.y,.06+.02*beatPulse(uBeatPhase,3.));
col=mix(col,vec3(.9,.3,.1)*copperBar(uv,uBeatPhase,5.),bar);
fragColor=vec4(finalize(col,uv),1.);
}
